import java.util.*;

class Solution {
  public int depthSum(List<NestedInteger> nestedList) {
    return sum(nestedList, 1);
  }

  private int sum(List<NestedInteger> list, int depth) {
    int total = 0;
    for (NestedInteger ni : list) total += ni.isInteger() ? ni.getInteger() * depth : sum(ni.getList(), depth + 1);
    return total;
  }
}
